            try { const d = el.getContext('2d').getImageData(0, 0, el.width, el.height).data; let n = 0; for (let i = 3; i < d.length; i += 32) if (d[i]) n++; if (!n) bad.push(label + ': canvas BLANK'); } catch (e) { /* tainted */ }
