                    return `<rect x="${sx - sr * 2}" y="${sy - sr * 2}" width="${sr * 4}" height="${sr * 4}" rx="${sr * 2}" fill="${sun.glow}" opacity="0.18"/>` +
                        `<rect x="${sx - sr}" y="${sy - sr}" width="${sr * 2}" height="${sr * 2}" rx="${sr}" fill="${sun.color}"/>`;
